logger.message:
#[%dw 2.0 
output application/json 
--- { 
	correlationId: vars.correlationId, 
	stagingCount: sizeOf(vars.stagingInvoices default [])
}]

set-variable.value:
#[output application/json
---
{
    "method"      : "GET",
    "host"        : Mule::p("linka.host"),
    "port"        : Mule::p("linka.port"),
    "path"        : Mule::p("linka.path.invoices"),
    "basePath"    : Mule::p("linka.basePath"),
    "queryParams" : {
        "sn": vars.currentStagingRow.InvoiceNumber
    },
    "headers": {
        "Authorization": "Bearer " ++ vars.accessToken.access
    }
}]

ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
do {
    var status = vars.currentStagingRow.status as Number
    var invoiceMatch = vars.currentStagingRow.InvoiceNumber == payload.sn
    var validForDelete = (payload.eval_status == 3) and ([0,1,2,4] contains status)
    var validForApprove = (payload.eval_status == 2) and ([0,1,4] contains status)
    ---
    if (status == null or payload.eval_status == null) null
    else if (invoiceMatch and (validForDelete or validForApprove)) payload
    else null
}
